pm.test("Content-Type header is application/json", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

// 4. Response body is a JSON array
pm.test("Response body is a JSON array", function () {
    const json = pm.response.json();
    pm.expect(json).to.be.an("array");
});

// 5. Array is not empty
pm.test("Response array is not empty", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.length.above(0);
});

// ── Per-pet validations ──────────────────────
const pets = pm.response.json();

if (Array.isArray(pets) && pets.length > 0) {

    // 6. Each pet has required fields: id, name, photoUrls, status
    pm.test("Each pet has required fields: id, name, photoUrls, status", function () {
        pets.forEach(function (pet, i) {
            pm.expect(pet, `pet[${i}] missing 'id'`).to.have.property("id");
            pm.expect(pet, `pet[${i}] missing 'name'`).to.have.property("name");
            pm.expect(pet, `pet[${i}] missing 'photoUrls'`).to.have.property("photoUrls");
            pm.expect(pet, `pet[${i}] missing 'status'`).to.have.property("status");
        });
    });

    // 7. Each pet's id is a number
    pm.test("Each pet's id is a number", function () {
        pets.forEach(function (pet, i) {
            pm.expect(pet.id, `pet[${i}].id`).to.be.a("number");
        });
    });

    // 8. Each pet's name is a non-empty string
    pm.test("Each pet's name is a non-empty string", function () {
        pets.forEach(function (pet, i) {
            pm.expect(pet.name, `pet[${i}].name`).to.be.a("string").and.to.have.length.above(0);
        });
    });

    // 9. Each pet's photoUrls is an array
    pm.test("Each pet's photoUrls is an array", function () {
        pets.forEach(function (pet, i) {
            pm.expect(pet.photoUrls, `pet[${i}].photoUrls`).to.be.an("array");
        });
    });

    // 10. Each pet's status is one of: "available", "pending", "sold"
    pm.test("Each pet's status is a valid value", function () {
        pets.forEach(function (pet, i) {
            pm.expect(VALID_STATUSES, `pet[${i}].status '${pet.status}' is not valid`).to.include(pet.status);
        });
    });

    // 11. Each pet has a tags array
    pm.test("Each pet has a tags array", function () {
        pets.forEach(function (pet, i) {
            pm.expect(pet, `pet[${i}] missing 'tags'`).to.have.property("tags");
            pm.expect(pet.tags, `pet[${i}].tags`).to.be.an("array");
        });
    });

    // 12. Each tag in the tags array has id and name fields
    pm.test("Each tag object has id and name fields", function () {
        pets.forEach(function (pet, i) {
            if (Array.isArray(pet.tags)) {
                pet.tags.forEach(function (tag, j) {
                    pm.expect(tag, `pet[${i}].tags[${j}] missing 'id'`).to.have.property("id");
                    pm.expect(tag, `pet[${i}].tags[${j}] missing 'name'`).to.have.property("name");
                });
            }
        });
    });

    // 13. At least one returned pet contains a tag matching the queried tag ("black pistols")
    pm.test(`At least one pet has a tag matching the queried tag "${QUERIED_TAG}"`, function () {
        const hasMatch = pets.some(function (pet) {
            return Array.isArray(pet.tags) && pet.tags.some(function (tag) {
                return typeof tag.name === "string" && tag.name.toLowerCase() === QUERIED_TAG.toLowerCase();
            });
        });
        pm.expect(hasMatch, `No pet found with tag name "${QUERIED_TAG}"`).to.be.true;
    });

    // 14. Category field (if present) has id and name
    pm.test("Category field (if present) has id and name", function () {
        pets.forEach(function (pet, i) {
            if (pet.category !== undefined && pet.category !== null) {
                pm.expect(pet.category, `pet[${i}].category missing 'id'`).to.have.property("id");
                pm.expect(pet.category, `pet[${i}].category missing 'name'`).to.have.property("name");
            }
        });
    });

}

